-- Placeholders like {{ run_id }} are filled in by the ELT DAG at run time.
-- Adds one f_<check> column per rule, plus dq_status, failure_reason, warning_reason
CREATE OR REPLACE TABLE stg_orders_flagged AS
SELECT *,
  CASE WHEN "f_order_id_not_null" OR "f_order_customer_id_not_null" OR "f_order_ts_not_null" OR "f_delivered_has_delivery_minutes" OR "f_order_id_unique" OR "f_order_ts_valid" OR "f_order_status_allowed" OR "f_order_payment_mode_allowed" OR "f_discount_pct_in_range" OR "f_quantity_positive_integer" OR "f_unit_price_positive" OR "f_order_amount_matches_formula" OR "f_delivery_minutes_plausible" OR "f_order_customer_exists" OR "f_order_product_exists" OR "f_order_store_exists" OR "f_order_ts_not_future" THEN 'FAIL' WHEN "f_order_status_standard" OR "f_order_payment_mode_standard" OR "f_delivery_minutes_normal_range" OR "f_unit_price_not_above_mrp" OR "f_delivered_has_success_payment" THEN 'WARN' ELSE 'PASS' END AS dq_status,
  NULLIF(concat_ws('; ', CASE WHEN "f_order_id_not_null" THEN 'order_id_not_null' END, CASE WHEN "f_order_customer_id_not_null" THEN 'order_customer_id_not_null' END, CASE WHEN "f_order_ts_not_null" THEN 'order_ts_not_null' END, CASE WHEN "f_delivered_has_delivery_minutes" THEN 'delivered_has_delivery_minutes' END, CASE WHEN "f_order_id_unique" THEN 'order_id_unique' END, CASE WHEN "f_order_ts_valid" THEN 'order_ts_valid' END, CASE WHEN "f_order_status_allowed" THEN 'order_status_allowed' END, CASE WHEN "f_order_payment_mode_allowed" THEN 'order_payment_mode_allowed' END, CASE WHEN "f_discount_pct_in_range" THEN 'discount_pct_in_range' END, CASE WHEN "f_quantity_positive_integer" THEN 'quantity_positive_integer' END, CASE WHEN "f_unit_price_positive" THEN 'unit_price_positive' END, CASE WHEN "f_order_amount_matches_formula" THEN 'order_amount_matches_formula' END, CASE WHEN "f_delivery_minutes_plausible" THEN 'delivery_minutes_plausible' END, CASE WHEN "f_order_customer_exists" THEN 'order_customer_exists' END, CASE WHEN "f_order_product_exists" THEN 'order_product_exists' END, CASE WHEN "f_order_store_exists" THEN 'order_store_exists' END, CASE WHEN "f_order_ts_not_future" THEN 'order_ts_not_future' END), '') AS failure_reason,
  NULLIF(concat_ws('; ', CASE WHEN "f_order_status_standard" THEN 'order_status_standard' END, CASE WHEN "f_order_payment_mode_standard" THEN 'order_payment_mode_standard' END, CASE WHEN "f_delivery_minutes_normal_range" THEN 'delivery_minutes_normal_range' END, CASE WHEN "f_unit_price_not_above_mrp" THEN 'unit_price_not_above_mrp' END, CASE WHEN "f_delivered_has_success_payment" THEN 'delivered_has_success_payment' END), '') AS warning_reason
FROM (
  SELECT t.*,
    COALESCE((t.order_id IS NULL), FALSE) AS "f_order_id_not_null",
    COALESCE((t.customer_id IS NULL), FALSE) AS "f_order_customer_id_not_null",
    COALESCE((t.order_ts_raw IS NULL), FALSE) AS "f_order_ts_not_null",
    COALESCE((t.order_status = 'DELIVERED' AND t.delivery_minutes IS NULL), FALSE) AS "f_delivered_has_delivery_minutes",
    COALESCE((t.order_id IS NOT NULL AND row_number() OVER (PARTITION BY t.order_id ORDER BY t._row) > 1), FALSE) AS "f_order_id_unique",
    COALESCE((t.order_ts_raw IS NOT NULL AND t.order_ts IS NULL), FALSE) AS "f_order_ts_valid",
    COALESCE((t.order_status IS NULL), FALSE) AS "f_order_status_allowed",
    COALESCE((t.payment_mode IS NULL), FALSE) AS "f_order_payment_mode_allowed",
    COALESCE((t.discount_pct IS NOT NULL AND (t.discount_pct < 0 OR t.discount_pct > 100)), FALSE) AS "f_discount_pct_in_range",
    COALESCE((t.order_status IS NOT NULL AND t.order_status_raw <> t.order_status), FALSE) AS "f_order_status_standard",
    COALESCE((t.payment_mode IS NOT NULL AND t.payment_mode_raw <> t.payment_mode), FALSE) AS "f_order_payment_mode_standard",
    COALESCE((t.quantity IS NULL OR t.quantity <= 0 OR t.quantity <> floor(t.quantity)), FALSE) AS "f_quantity_positive_integer",
    COALESCE((t.unit_price IS NULL OR t.unit_price <= 0), FALSE) AS "f_unit_price_positive",
    COALESCE((t.order_amount IS NULL OR t.quantity IS NULL OR t.unit_price IS NULL OR abs(t.order_amount - t.quantity * t.unit_price * (1 - coalesce(t.discount_pct, 0) / 100)) > 0.01), FALSE) AS "f_order_amount_matches_formula",
    COALESCE((t.delivery_minutes IS NOT NULL AND (t.delivery_minutes <= 0 OR t.delivery_minutes >= 120)), FALSE) AS "f_delivery_minutes_plausible",
    COALESCE((t.delivery_minutes > 0 AND t.delivery_minutes < 120 AND (t.delivery_minutes < 8 OR t.delivery_minutes > 35)), FALSE) AS "f_delivery_minutes_normal_range",
    COALESCE((t.customer_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ref_customers r WHERE r.customer_id = t.customer_id)), FALSE) AS "f_order_customer_exists",
    COALESCE((t.product_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ref_products r WHERE r.product_id = t.product_id)), FALSE) AS "f_order_product_exists",
    COALESCE((t.store_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ref_stores r WHERE r.store_id = t.store_id)), FALSE) AS "f_order_store_exists",
    COALESCE((EXISTS (SELECT 1 FROM ref_product_mrp r WHERE r.product_id = t.product_id AND t.unit_price > r.mrp + 0.01)), FALSE) AS "f_unit_price_not_above_mrp",
    COALESCE((t.order_status = 'DELIVERED' AND t.order_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ref_payments r WHERE r.order_id = t.order_id AND r.payment_status = 'SUCCESS')), FALSE) AS "f_delivered_has_success_payment",
    COALESCE((t.order_ts >= TIMESTAMP '{{ next_day }}'), FALSE) AS "f_order_ts_not_future"
  FROM stg_orders_std t
) AS flagged;
